arguments:
item -> {
                  InstallationTarget installationTarget =
                      item.installationTarget() != null
                          ? new InstallationTarget.Vin(item.installationTarget().vin())
                          : null;
                  return new CartLineItem(
                      item.productVariantId(), item.financingOfferVariantId(), installationTarget);
                }

receiver:
input.items().stream()
            .map(
                item -> {
                  InstallationTarget installationTarget =
                      item.installationTarget() != null
                          ? new InstallationTarget.Vin(item.installationTarget().vin())
                          : null;
                  return new CartLineItem(
                      item.productVariantId(), item.financingOfferVariantId(), installationTarget);
                })
